import { LOCALES } from "@pantoken/web-components";
import chromeSource from "./i18n.json" with { type: "json" };
import type { AgentToolsStrings } from "./theme/agent-tools.ts";
import type { CanvasRceStrings } from "./theme/canvas-rce.ts";
import type { CdnPickerStrings } from "./theme/cdn.ts";
import type { GetStartedTabsStrings } from "./theme/get-started.ts";
import type { RegistryBrowserStrings } from "./theme/registry.ts";
import type { A2uiCatalogStrings } from "./theme/a2ui-catalog.ts";
import { loadConfig, resolveMessagesForLocale, resolveTier } from "@pantoken/i18n-engine";

/** Generated CSS API prose enters the existing glossary/prose API translation pipeline. */
export const ACCESSIBILITY_AUDIT_STRINGS = {
  notAudited:
    "Not audited: no checked-in evidence covers this record. Results from other components don't establish coverage for this one.",
  pass: "Pass",
  fail: "Fail",
  review: "Review needed",
  notApplicable: "Not applicable",
  rules: "Rules (axe-core)",
  conditions: "Conditions",
  interactions: "Interactions",
  computed: "Computed styles",
  screenReader: "Screen reader (simulated)",
  announcements: "Announcements",
  noResult: "No result was recorded for this check; test it manually.",
  columns: {
    "rebrand/light": "Rebrand (light)",
    "rebrand/dark": "Rebrand (dark)",
    "canvas/light": "Canvas",
    "canvasHighContrast/light": "Canvas High Contrast",
  },
  caveat:
    "These automated results do not establish that the page meets WCAG; manual review is still needed.",
} as const;

/**
 * Every locale the docs site builds: `root` (English) plus every non-`en` locale from
 * `@pantoken/web-components`'s `LOCALES` (44 BCP47 tags — `en` is dropped since `root` already covers
 * US English). English regional variants (`en-AU`, `en-CA`, `en-GB`) get their own route prefix AND
 * their own translated UI strings — British/Australian/Canadian spelling and phrasing differ from US
 * English (colour/centre, -ise vs. -ize, etc.), so they go through the same translation pipeline as
 * every other locale rather than passing through the `root` English source untouched.
 * `LOCALES` is typed as `Record<string, LocaleInfo>` (its keys aren't a literal union), so
 * `DocsLocale` is a plain `string`.
 */
export type DocsLocale = string;

/** The non-`root` locale keys, in `LOCALES` order. */
export const NON_ROOT_LOCALES = Object.keys(LOCALES).filter((key) => key !== "en");

/**
 * Resolve a `DOCS_TRANSLATION_LOCALE` value — one entry or a comma/space-separated list — against
 * `fallback` (every locale when the variable is unset). Each entry is either a locale tag or a tier
 * name from `i18n.config.json`'s `locales.tiers` (`primary`, `secondary`, …), which expands to every
 * docs locale in that tier; the two can be mixed. Prefix an entry with `-` to subtract it, e.g.
 * `"-ga"` for every locale but Irish or `"primary,-hu"` for the primary tier without Hungarian; a
 * value of only subtractions starts from `fallback`. Throws on an entry that's neither a tag nor a
 * tier, so a typo fails loudly instead of quietly building an empty directory.
 */
export const parseRequestedLocales = (
  requested: string | undefined,
  fallback: readonly string[],
): readonly string[] => {
  const entries = (requested ?? "").split(/[,\s]+/).filter((entry) => entry.length > 0);
  if (entries.length === 0) return fallback;

  const tiers = loadConfig(new URL("../../i18n.config.json", import.meta.url).pathname).locales
    .tiers;
  const unknown: string[] = [];
  const expand = (entry: string): readonly string[] => {
    // resolveTier, not a raw pattern match: tiers are ordered, so `secondary`'s `"*"` must not
    // reclaim a locale that `primary` already matched.
    if (entry in tiers) return NON_ROOT_LOCALES.filter((l) => resolveTier(tiers, l) === entry);
    if (NON_ROOT_LOCALES.includes(entry)) return [entry];
    unknown.push(entry);
    return [];
  };

  const included: string[] = [];
  const excluded = new Set<string>();
  let hasInclude = false;
  for (const entry of entries) {
    if (entry.startsWith("-")) for (const locale of expand(entry.slice(1))) excluded.add(locale);
    else {
      hasInclude = true;
      included.push(...expand(entry));
    }
  }
  if (unknown.length > 0) {
    throw new Error(
      `Unknown DOCS_TRANSLATION_LOCALE value(s): ${unknown.join(", ")}. Supported tiers: ${Object.keys(tiers).join(", ")}. Supported locales: ${NON_ROOT_LOCALES.join(", ")}`,
    );
  }

  // Only subtractions (`"-ga"`) start from every locale; an include that expanded to nothing must not.
  const base = hasInclude ? included : fallback;
  const resolved = [...new Set(base)].filter((locale) => !excluded.has(locale));
  // A tier can be valid yet empty here — `source` is `["en"]`, which no docs locale belongs to.
  if (resolved.length === 0) {
    throw new Error(`DOCS_TRANSLATION_LOCALE=${requested ?? ""} matched no docs locale`);
  }
  return resolved;
};

/** Every docs locale, `root` first. */
const ALL_DOCS_LOCALES: readonly DocsLocale[] = ["root", ...NON_ROOT_LOCALES];

/**
 * Non-Latin scripts have a purpose-drawn wordmark in `@pantoken/plugin-logos`, keyed by the script
 * suffix here. `docs/scripts/stage-locale-logos.ts` copies those into
 * `docs/public/logo-{light,dark}-<script>.svg` for the nav, and `docs/scripts/gen-og.ts` sets the same
 * mark on the locale's social card. `zh-Hans`/`zh-Hant` share one Han-script mark; the Japanese file
 * is suffixed `jp`.
 */
export const NON_LATIN_LOCALES: Partial<Record<DocsLocale, string>> = {
  ar: "ar",
  el: "el",
  fa: "fa",
  he: "he",
  hi: "hi",
  hy: "hy",
  ja: "jp",
  ko: "ko",
  ru: "ru",
  th: "th",
  uk: "uk",
  "zh-Hans": "zh",
  "zh-Hant": "zh",
};

/**
 * Translatable UI chrome — everything that gets translated into the `docs.chrome` PO catalog (see
 * `docs/.vitepress/i18n.json`). Structural, non-translated metadata (route prefixes, the
 * TypeDoc sidebar path, the BCP47 tag, text direction) lives in {@link LocaleStructure} instead.
 */
export interface UiStrings {
  description: string;
  nav: { guide: string; css: string; api: string };
  sidebar: {
    intro: string;
    guides: string;
    utilities: string;
    gettingStarted: string;
    architecture: string;
    components: string;
    cdn: string;
    cdnPicker: string;
    registry: string;
    a2uiCatalog: string;
    agentTools: string;
    canvasRce: string;
    cli: string;
    plugins: string;
    generated: string;
    api: string;
    css: string;
    apiGroups: {
      ai: string;
      bundlers: string;
      design: string;
      formats: string;
      packages: string;
      platforms: string;
      plugins: string;
      renderers: string;
      tools: string;
    };
    apiOverview: string;
  };
  editText: string;
  // Screen-reader label for the hero's rotating `.platform` pill, which otherwise only announces
  // whichever platform name is currently cycling in (see theme/components/VPHomeHero.vue).
  platformPicker: { label: string };
  // View tabs on the `@pantoken/demo` runner, passed into its iframe by the markdown-it plugin.
  // The language names are acronyms, so most locales keep them as-is.
  demoTabs: { result: string; html: string; css: string; js: string };
  // The pantoken palette selector injected into the nav by the custom theme (see ThemeSelector.vue).
  // `Canvas` is an Instructure product name and stays as-is per brand rules; only descriptors translate.
  themeSelector: {
    label: string;
    rebrand: string;
    canvas: string;
    canvasHighContrast: string;
    colorLabel?: string;
    navy?: string;
    blue?: string;
    green?: string;
    red?: string;
    orange?: string;
    grey?: string;
    ash?: string;
    plum?: string;
    violet?: string;
    stone?: string;
    sky?: string;
    honey?: string;
    sea?: string;
    aurora?: string;
    custom?: string;
    customColorInputLabel?: string;
  };
  // The interactive CDN combine-URL builder on the CDN guide page (see theme/components/CdnPicker.vue
  // and theme/cdn.ts). Component names and the generated URL are not translated.
  cdnPicker: CdnPickerStrings;
  // The "Get started" scaffold tabs (see theme/components/GetStartedTabs.vue and theme/get-started.ts).
  // Only the AI tab's instructions are prose; the other tabs' `npx …` commands are not translated.
  getStartedTabs: GetStartedTabsStrings;
  // The shadcn/ui registry browser (see theme/components/RegistryBrowser.vue and theme/registry.ts).
  registryBrowser: RegistryBrowserStrings;
  a2uiCatalog: A2uiCatalogStrings;
  // The interactive Agent Tools utility (see theme/components/AgentToolsPage.vue and
  // theme/agent-tools.ts).
  agentTools: AgentToolsStrings;
  // The Canvas RCE utility page embedding the canvas-theme-editor scaffold's live TinyMCE editor (see
  // theme/components/CanvasRcePage.vue and theme/canvas-rce.ts).
  canvasRce: CanvasRceStrings;
  // Default-theme chrome VitePress renders around the content. Without these an untranslated locale
  // shows English labels (outline heading, prev/next footer, dark-mode toggle, the 404 page, etc.).
  chrome: {
    outlineLabel: string;
    docFooterPrev: string;
    docFooterNext: string;
    darkModeSwitchLabel: string;
    lightModeSwitchTitle: string;
    darkModeSwitchTitle: string;
    sidebarMenuLabel: string;
    returnToTopLabel: string;
    langMenuLabel: string;
    sidebarToggleLabel: string;
    lastUpdatedText: string;
    agentShellPrompt: string;
    notFound: {
      code: string;
      title: string;
      quote: string;
      linkLabel: string;
      linkText: string;
    };
  };
  // Local-provider search UI. Wired into the global `themeConfig.search.options.locales` (the search
  // index reads the root themeConfig, not the per-route one), keyed by locale.
  search: {
    buttonText: string;
    displayDetails: string;
    resetButtonTitle: string;
    backButtonTitle: string;
    noResultsText: string;
    footerSelect: string;
    footerNavigate: string;
    footerClose: string;
  };
}

/** The English source of truth for every translatable UI string in {@link UiStrings}. */
const sourceUiStrings = Object.fromEntries(
  Object.entries(chromeSource)
    .filter(([key]) => key !== "$schema")
    .map(([key, entry]) => [key, (entry as { message: string }).message]),
);

function unflattenStrings(flat: Record<string, string>): UiStrings {
  const result: Record<string, unknown> = {};
  for (const [path, value] of Object.entries(flat)) {
    const parts = path.split(".");
    let target = result;
    for (const part of parts.slice(0, -1)) {
      target[part] ??= {};
      target = target[part] as Record<string, unknown>;
    }
    target[parts.at(-1)!] = value;
  }
  return result as unknown as UiStrings;
}

/** English UI strings used as the fallback for localized documentation chrome. */
export const ENGLISH_UI_STRINGS: UiStrings = unflattenStrings(sourceUiStrings);

/** Structural, non-translated per-locale metadata: route prefixes, BCP47 tag, direction, sidebar path. */
export interface LocaleStructure {
  label: string;
  lang: string;
  dir: "ltr" | "rtl";
  guidePrefix: string;
  apiPrefix: string;
  // The CSS reference is merged into the TypeDoc sidebar by `@cssdoc/typedoc`, so there's one path.
  typedocSidebarPath: string;
}

const structureFor = (locale: DocsLocale): LocaleStructure => {
  if (locale === "root") {
    return {
      label: "English",
      lang: "en-US",
      dir: "ltr",
      guidePrefix: "/guide/",
      apiPrefix: "/api/",
      typedocSidebarPath: "../api/typedoc-sidebar.json",
    };
  }
  const meta = LOCALES[locale];
  return {
    label: meta.label,
    lang: locale,
    dir: meta.dir,
    guidePrefix: `/${locale}/guide/`,
    apiPrefix: `/${locale}/api/`,
    typedocSidebarPath: `../${locale}/api/typedoc-sidebar.json`,
  };
};

/** Recursively collect every leaf string in an object tree, keyed by its dotted path. */
export function flattenStrings(value: unknown, prefix = ""): { path: string; text: string }[] {
  if (typeof value === "string") return [{ path: prefix, text: value }];
  if (value && typeof value === "object") {
    return Object.entries(value as Record<string, unknown>).flatMap(([key, child]) =>
      flattenStrings(child, prefix ? `${prefix}.${key}` : key),
    );
  }
  return [];
}

/** Deep-clone `base`, overwriting each leaf whose dotted path is in `overrides`. */
function applyOverrides<T>(base: T, overrides: ReadonlyMap<string, string>, prefix = ""): T {
  if (typeof base === "string") {
    return (overrides.get(prefix) ?? base) as T;
  }
  if (base && typeof base === "object") {
    const out: Record<string, unknown> = { ...(base as Record<string, unknown>) };
    for (const [key, child] of Object.entries(base as Record<string, unknown>)) {
      out[key] = applyOverrides(child, overrides, prefix ? `${prefix}.${key}` : key);
    }
    return out as T;
  }
  return base;
}

// Every UI leaf, computed once — reused by the docs chrome renderer and drift checker.
const ENGLISH_UI_LEAVES = flattenStrings(ENGLISH_UI_STRINGS);

/**
 * Resolve the locale's `docs.chrome` PO catalog over the English defaults, so untranslated strings
 * fall back to English rather than disappearing.
 */
const uiStringsFor = (locale: DocsLocale): UiStrings => {
  if (locale === "root") return ENGLISH_UI_STRINGS;
  const config = loadConfig(new URL("../../i18n.config.json", import.meta.url).pathname);
  const resolved = resolveMessagesForLocale(
    config,
    new URL("../../", import.meta.url).pathname,
    "docs.chrome",
    locale,
  );
  const overrides = new Map(ENGLISH_UI_LEAVES.map(({ path }) => [path, resolved.strings[path]]));
  return applyOverrides(ENGLISH_UI_STRINGS, overrides);
};

/** Per-locale route structure plus all translated UI chrome strings. */
export type LocaleTheme = LocaleStructure & UiStrings;

// Computed lazily (and memoized) behind a Proxy: merely importing this module — e.g. for
// `NON_ROOT_LOCALES`/`ENGLISH_UI_STRINGS`/`flattenStrings` stay cheap to import; PO resolution only
// runs once something actually reads a `LOCALE_THEMES` property (the real docs build).
let computedLocales: Record<DocsLocale, LocaleTheme> | undefined;
const computeLocales = (): Record<DocsLocale, LocaleTheme> => {
  computedLocales ??= Object.fromEntries(
    ALL_DOCS_LOCALES.map((locale) => [
      locale,
      { ...structureFor(locale), ...uiStringsFor(locale) },
    ]),
  ) as Record<DocsLocale, LocaleTheme>;
  return computedLocales;
};

/** Per-locale metadata — route prefixes, nav/sidebar labels, and all translated UI chrome. */
export const LOCALE_THEMES: Record<DocsLocale, LocaleTheme> = new Proxy(
  {} as Record<DocsLocale, LocaleTheme>,
  {
    get: (_target, prop) => computeLocales()[prop as DocsLocale],
    has: (_target, prop) => prop in computeLocales(),
    ownKeys: () => Reflect.ownKeys(computeLocales()),
    getOwnPropertyDescriptor: (_target, prop) =>
      Object.getOwnPropertyDescriptor(computeLocales(), prop),
  },
);

/** Localized labels for the A2UI catalog browser. */
export interface A2uiCatalogStrings {
  title: string;
  subtitle: string;
  protocolLabel: string;
  catalogIdLabel: string;
  rawCatalog: string;
  componentsHeading: string;
  searchLabel: string;
  searchPlaceholder: string;
  required: string;
  optional: string;
  noFunctions: string;
  supportHeading: string;
  litSupport: string;
  reactSupport: string;
  angularSupport: string;
  nativeSupport: string;
  integrationHeading: string;
  componentReference: string;
  empty: string;
}

import { readFileSync } from "node:fs";
import { expect, test } from "vite-plus/test";
import { validateCatalog } from "../scripts/generate-a2ui-catalog.ts";

type CatalogFixture = {
  protocolVersion: string;
  components: Record<string, { properties: Record<string, unknown> }>;
  [key: string]: unknown;
};

function readCatalog(): CatalogFixture {
  return JSON.parse(
    readFileSync(new URL("../catalogs/pantoken-v1.json", import.meta.url), "utf8"),
  ) as CatalogFixture;
}

test("validates the checked-in Pantoken A2UI 1.0 catalog", () => {
  expect(() => validateCatalog(readCatalog())).not.toThrow();
});

test("rejects unlisted component properties and executable catalog functions", () => {
  const withExtraProperty = readCatalog();
  withExtraProperty.components.PantokenButton.properties.href = {
    type: "string",
    format: "uri",
  };
  expect(() => validateCatalog(withExtraProperty)).toThrow(/properties must be exactly/);

  const withFunctions = readCatalog();
  withFunctions.functions = {};
  expect(() => validateCatalog(withFunctions)).toThrow(/does not publish executable/);
});

